def encode(s: str) -> str:
    """Encodes a string by shifting characters in 3-char groups: first char moved to end."""
    return ''.join(s[i+1:i+3] + s[i] if i % 3 == 0 and i+2 < len(s) else s[i] 
                   for i in range(len(s)))

def decode(s: str) -> str:
    """Decodes a string by shifting characters in 3-char groups: last char moved to start."""
    return ''.join(s[i-1:i+1] + s[i+1] if (i+1) % 3 == 0 and i > 0 and i+1 < len(s) 
                   else s[i] for i in range(len(s)))

# Example usage:
