def parse_nested_parens(paren_string: str) -> list[int]:
    """
    Parses a string containing space-separated sequences of parentheses
    and returns a list of maximum nesting depths for each sequence.
    """
    def count_depth(seq: str) -> int:
        """Calculates the maximum nesting depth of a single parenthesis sequence."""
        depth = 0
        max_depth = 0
        for char in seq:
            if char == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif char == ')':
                depth -= 1
        return max_depth

    # Split by spaces, filter out empty strings, and map each sequence to its depth
    return [
        count_depth(seq) 
        for seq in paren_string.split() 
        if seq  # Filters out empty strings
    ]
